def sum_prefix_scores(words):
    root=[0,{}]
    for word in words:
        node=root
        for char in word:
            node=node[1].setdefault(char,[0,{}]);node[0]+=1
    answer=[]
    for word in words:
        node=root;score=0
        for char in word:
            node=node[1][char];score+=node[0]
        answer.append(score)
    return answer

